import math

# We need to solve 8*v^3 - u^3 = 5 for integers u, v.
# u^3 = 8*v^3 - 5

def is_perfect_cube(N):
    if N == 0:
        return 0

    # Use float exponentiation and rounding for approximation
    abs_N = abs(N)
    root_approx = round(abs_N**(1/3))

    # Check if the approximation is the true integer cube root
    if root_approx**3 == abs_N:
        if N > 0:
            return root_approx
        else:
            return -root_approx
    return None

def solve_equation(V_limit):
    solutions = []
    for v in range(-V_limit, V_limit + 1):
        target_u3 = 8 * (v**3) - 5

        u = is_perfect_cube(target_u3)

        if u is not None:
            # Check coprime condition
            if math.gcd(u, v) == 1:
                solutions.append((u, v))

    return solutions

# Search range for v: Let's increase it slightly to |v| = 10 just to be safe, 
# although likely small solutions exist.
solutions = solve_equation(10)
print(solutions)

import math

def find_solutions(target):
    solutions = []
    # Check v from -10 to 10
    for v in range(-10, 11):
        # Calculate u^3 = 8*v^3 - target
        u_cubed = 8 * (v**3) - target

        # Check if u_cubed is a perfect cube
        if u_cubed >= 0:
            u_candidate = round(u_cubed**(1/3))
            if u_candidate**3 == u_cubed:
                u = u_candidate
                if math.gcd(u, v) == 1:
                    solutions.append((u, v))
        else:
            # Check for negative cubes
            u_candidate = -round((-u_cubed)**(1/3))
            if u_candidate**3 == -u_cubed:
                u = u_candidate
                if math.gcd(u, v) == 1:
                    solutions.append((u, v))

    return solutions

target = 13
solutions = find_solutions(target)
print(f"Solutions (u, v) for 8v^3 - u^3 = 13: {solutions}")
